body{margin:0;font-family:"Open Sans","Inter","Segoe UI",Arial,sans-serif;color:#1f2937;background:#ffffff;}
.wrap{display:flex;flex-direction:column;height:100%;background:#ffffff;border:1px solid #e5e7eb;border-radius:6px;overflow:hidden;}
.meta{padding:8px 16px 0;color:#64748b;font-size:13px;}
.scroll{overflow:auto;flex:1;}
.tbl{width:100%;border-collapse:collapse;font-size:13px;table-layout:fixed;}
.tbl th{text-align:left;padding:12px 14px;color:#334155;font-weight:700;font-size:13px;background:#ffffff;border-bottom:1px solid #e2e8f0;cursor:pointer;user-select:none;white-space:nowrap;position:sticky;top:0;z-index:1;}
.tbl th.noSort{cursor:default;}
.tbl th .sort{display:inline-flex;flex-direction:column;margin-left:6px;line-height:0.7;vertical-align:middle;}
.tbl th .sort span{font-size:9px;color:#cbd5e1;}
.tbl th .sort span.active{color:#334155;}
.tbl td{padding:11px 14px;border-bottom:1px solid #eef2f7;color:#1f2937;vertical-align:top;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.tbl td.desc,.tbl td.event{white-space:normal;word-break:break-word;}
.tbl tbody tr:nth-child(even) td{background:#f7f8fa;}
.tbl tbody tr:hover td{background:#eef4ff;}
.badge{display:inline-block;padding:2px 10px;border-radius:12px;font-size:12px;font-weight:600;}
.b-error{background:#fee2e2;color:#b91c1c;}
.b-warning{background:#fef3c7;color:#b45309;}
.empty{padding:36px;text-align:center;color:#94a3b8;font-style:italic;}
.pager{display:flex;align-items:center;gap:8px;padding:12px 16px;border-top:1px solid #e5e7eb;background:#ffffff;}
.pbtn{background:transparent;border:1px solid #e2e8f0;color:#334155;cursor:pointer;padding:5px 10px;border-radius:4px;font-size:14px;}
.pbtn:disabled{color:#cbd5e1;cursor:not-allowed;border-color:#f1f5f9;}
.pbtn:hover:not(:disabled){background:#f1f5f9;}
.pnum{min-width:28px;text-align:center;background:#2563eb;color:#ffffff;border-radius:4px;padding:5px 10px;font-weight:600;}
.gotolbl{color:#64748b;font-size:13px;}
.goto{width:54px;padding:5px 8px;border:1px solid #e2e8f0;border-radius:4px;font-size:13px;outline:none;color:#1f2937;}
.psize{margin-left:auto;background:#ffffff;color:#334155;border:1px solid #e2e8f0;border-radius:4px;padding:5px 10px;font-size:13px;outline:none;cursor:pointer;}
.skel{padding:20px;color:#64748b;}

